CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE connections (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), integration_id TEXT NOT NULL, endpoint TEXT NOT NULL, UNIQUE(org_id, integration_id));
CREATE TABLE executions (id TEXT PRIMARY KEY, saga_id TEXT NOT NULL, saga_name TEXT NOT NULL, saga_revision TEXT NOT NULL, org_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL, input_json TEXT NOT NULL CHECK(length(input_json) <= 4096), dispatched INTEGER NOT NULL DEFAULT 0 CHECK(dispatched IN (0, 1)), status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending', 'Running', 'Succeeded', 'Failed', 'TimedOut', 'Cancelled')), created_at TEXT NOT NULL, started_at TEXT, completed_at TEXT, result_json TEXT CHECK(result_json IS NULL OR length(result_json) <= 4096), error_json TEXT);
CREATE INDEX executions_history ON executions(org_id, user_id, created_at DESC, id DESC);
CREATE TABLE operations (execution_id TEXT NOT NULL REFERENCES executions(id), name TEXT NOT NULL, position INTEGER NOT NULL CHECK(position >= 0), status TEXT NOT NULL CHECK(status IN ('Running', 'Succeeded', 'Failed')), started_at TEXT NOT NULL, completed_at TEXT, result_json TEXT CHECK(result_json IS NULL OR length(result_json) <= 4096), error_json TEXT, PRIMARY KEY(execution_id, name));
